do $$ begin if not exists (select 1 from pg_roles where rolname='sekinfra_consulting_service') then create role sekinfra_consulting_service nologin nobypassrls nosuperuser nocreatedb nocreaterole noinherit; end if; end $$; grant usage on schema public to sekinfra_consulting_service; alter table public.sekinfra_diagnostic_agreement_authorities enable row level security; alter table public.sekinfra_diagnostic_payment_verifications enable row level security; alter table public.sekinfra_assessment_access_proposals enable row level security; alter table public.sekinfra_assessment_access_grants enable row level security; revoke all on table public.sekinfra_acquisition_handoffs,public.sekinfra_engagements,public.sekinfra_diagnostic_scopes,public.sekinfra_human_approvals,public.sekinfra_idempotency_records,public.sekinfra_lifecycle_events,public.sekinfra_outbox_deliveries,public.sekinfra_diagnostic_agreement_authorities,public.sekinfra_diagnostic_payment_verifications,public.sekinfra_assessment_access_proposals,public.sekinfra_assessment_access_grants from anon,authenticated,public; grant select on table public.sekinfra_acquisition_handoffs,public.sekinfra_engagements,public.sekinfra_diagnostic_scopes,public.sekinfra_human_approvals,public.sekinfra_idempotency_records,public.sekinfra_lifecycle_events,public.sekinfra_outbox_deliveries,public.sekinfra_diagnostic_agreement_authorities,public.sekinfra_diagnostic_payment_verifications,public.sekinfra_assessment_access_proposals,public.sekinfra_assessment_access_grants to sekinfra_consulting_service; grant insert on table public.sekinfra_engagements,public.sekinfra_diagnostic_scopes,public.sekinfra_human_approvals,public.sekinfra_idempotency_records,public.sekinfra_lifecycle_events,public.sekinfra_outbox_deliveries,public.sekinfra_diagnostic_agreement_authorities,public.sekinfra_diagnostic_payment_verifications,public.sekinfra_assessment_access_proposals,public.sekinfra_assessment_access_grants to sekinfra_consulting_service; grant update (accepted_at) on public.sekinfra_acquisition_handoffs to sekinfra_consulting_service; grant update (status,effective_at,canonical_scope_digest,record_version) on public.sekinfra_diagnostic_scopes to sekinfra_consulting_service; grant update (verification_status,invalidated_at,record_version) on public.sekinfra_diagnostic_payment_verifications to sekinfra_consulting_service; grant update (status,consumed_at,record_version) on public.sekinfra_assessment_access_proposals to sekinfra_consulting_service; grant update (status,verified_at,active_from,expires_at,revoked_at,closed_at,closure_reason,record_version) on public.sekinfra_assessment_access_grants to sekinfra_consulting_service; grant update (processing_status,result_reference,completed_at,record_version) on public.sekinfra_idempotency_records to sekinfra_consulting_service; do $$ declare t text; begin foreach t in array array['sekinfra_acquisition_handoffs','sekinfra_engagements','sekinfra_diagnostic_scopes','sekinfra_human_approvals','sekinfra_idempotency_records','sekinfra_lifecycle_events','sekinfra_outbox_deliveries','sekinfra_diagnostic_agreement_authorities','sekinfra_diagnostic_payment_verifications','sekinfra_assessment_access_proposals','sekinfra_assessment_access_grants'] loop execute format('create policy sekinfra_consulting_service_tenant_isolation on public.%I for all to sekinfra_consulting_service using (tenant_id = nullif(current_setting(''sekinfra.tenant_id'',true),'''')::uuid) with check (tenant_id = nullif(current_setting(''sekinfra.tenant_id'',true),'''')::uuid)',t); end loop; end $$;
